local Player2DBadgeMovableEntity = Class('Player2DBadgeMovableEntity')

-- ========================================================

--- lua:


local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Vector3 = CS.UnityEngine.Vector3
local UISwitchImage = CS.Game.Native.Common.UISwitchImage


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

---@type Interfaces
local Interfaces = Interfaces

local gameUtils = GameUtils

-- ========================================================


function Player2DBadgeMovableEntity:__init()
    --print("   ~~~~~~~ Player2DBadgeMovableEntity:__init() ~~~~~~~")
    self.controller = nil
    self.co = nil   -- 发送携程请求
end


function Player2DBadgeMovableEntity:__delete()
    --print("   ~~~~~~~ Player2DBadgeMovableEntity:__delete() ~~~~~~~")
    self.co = nil
end



function Player2DBadgeMovableEntity:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --print("   ~~~~~~~ Player2DBadgeMovableEntity:Awake() ~~~~~~~")
    KTool.SetActive(self.ImgSelect, false)
    ---
    local saveImgCloseTF = self.BtnSave.transform:Find("ImgClose")
    self.saveUISwitchImage = KTool.GetComponent(saveImgCloseTF.gameObject, typeof(UISwitchImage))
end



function Player2DBadgeMovableEntity:Init( badgeId_, photoPath_ )

    -- 也许是 没必要的
    --self.badgeIdx = badgeIdx_
    self.badgeId = badgeId_

    self:DrawBadge( photoPath_ )
end




function Player2DBadgeMovableEntity:OnDestroy()

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    --print("   ~~~~~~~ Player2DBadgeMovableEntity:OnDestroy() ~~~~~~~")
end


-- =============================================================



function Player2DBadgeMovableEntity:DrawBadge( photoPath_ )


    CfUtils.FillImage(self.ImgIcon, photoPath_)


end


function Player2DBadgeMovableEntity:ShowFrame( params_  ) 
    if type(params_)~="table" or isNull(params_.isShow) or isNull(params_.isRed) or isNull(params_.isEdit) then 
        printError( "koko 参数 params 异常" )
        return
    end
    ---
    KTool.SetActive(self.ImgSelect, params_.isShow == true)
    if params_.isShow == true then 
        self.ImgSelect.Status = (params_.isRed and 2 or 1)
        if isNotNull(self.saveUISwitchImage) then 
            self.saveUISwitchImage.Status = (params_.isRed and 2 or 1) -- 红框右上角 打勾 也要置灰
        end 

        KTool.SetActive(self.BtnSave, params_.isEdit == true)
        KTool.SetActive(self.BtnCancel, params_.isEdit == true)
    end


end 









return Player2DBadgeMovableEntity
